345.               name="${config.name}"
346.               type="${config.type}"
347.               ${config.required ? "required" : ""}
348.               autocomplete="${config.autocomplete}"
349.               aria-describedby="${config.describedBy.join(" ")}"
350.               aria-errormessage="${config.errorId}"
351.             />
352.             ${helpMarkup}
353.             <p id="${config.errorId}" class="field-error" hidden></p>
354.           </div>
