380.                 label: "Email address",
381.                 type: "email",
382.                 required: true,
383.                 autocomplete: "email",
384.                 describedBy: ["email-address-error"],
385.                 errorId: "email-address-error"
386.               })}
387.               ${FormField({
388.                 id: "phone-number",
389.                 name: "phone",
390.                 label: "Phone number",
391.                 type: "tel",
392.                 required: false,
393.                 autocomplete: "tel",
394.                 describedBy: ["phone-number-help", "phone-number-error"],
395.                 helpId: "phone-number-help",
396.                 helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
397.                 errorId: "phone-number-error"
398.               })}
399.               <div class="submit-row">
400.                 <button type="submit">Send request</button>
401.                 <p id="form-status" class="form-status" aria-live="polite"></p>
402.               </div>
