410.       const form = document.getElementById("support-form");
411.       const status = document.getElementById("form-status");
412.       const fieldConfig = {
413.         fullName: {
414.           input: document.getElementById("full-name"),
415.           error: document.getElementById("full-name-error"),
416.           validate(value) {
417.             return value.trim() ? "" : "Error: Enter your full name.";
418.           }
419.         },
420.         email: {
421.           input: document.getElementById("email-address"),
422.           error: document.getElementById("email-address-error"),
423.           validate(value, input) {
424.             if (!value.trim()) {
425.               return "Error: Enter your email address.";
426.             }
427. 
428.             return input.validity.typeMismatch ? "Error: Enter an email address like name@example.com." : "";
429.           }
430.         },
431.         phone: {
432.           input: document.getElementById("phone-number"),
433.           error: document.getElementById("phone-number-error"),
434.           validate(value) {
435.             if (!value.trim()) {
436.               return "";
437.             }
438. 
439.             const phonePattern = /^[+]?[\d\s().-]{7,}$/;
440.             return phonePattern.test(value.trim())
441.               ? ""
442.               : "Error: Enter a phone number in a format like (555) 123-4567.";
443.           }
444.         }
445.       };
