487.         event.preventDefault();
488.         hasSubmitted = true;
489.         status.textContent = "";
490. 
491.         const invalidFields = Object.keys(fieldConfig).filter((name) => {
492.           const message = validateField(name);
493.           return Boolean(message);
494.         });
