  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="root"></div>
    <script>
      function App() {
        return `
          <main id="maincontent" class="page-shell" tabindex="-1">
            <div class="support-layout">
              ${SupportCopy()}
              ${SupportForm()}
            </div>
          </main>
        `;
      }

      function SupportCopy() {
        return `
          <section class="support-copy" aria-labelledby="support-title">
            <span class="eyebrow">Support team</span>
            <h1 id="support-title">Get help from our product specialists.</h1>
            <p class="lead">
              Reach out with account questions, onboarding issues, or product feedback and our team
              will route your request to the right specialist.
            </p>
            <ul class="feature-list" aria-label="Support highlights">
              <li>
                <strong>Fast triage</strong>
                Requests land with the right team from the start.
              </li>
              <li>
                <strong>Clear follow-up</strong>
                Required contact details help us reply without delay.
              </li>
              <li>
                <strong>Flexible contact</strong>
                Add a phone number if a call is easier for you.
              </li>
            </ul>
          </section>
        `;
      }

      function FormField(config) {
        const helpMarkup = config.helpText
          ? `<p id="${config.helpId}" class="field-help">${config.helpText}</p>`
          : "";

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${config.id}"
              name="${config.name}"
              type="${config.type}"
              ${config.required ? "required" : ""}
              autocomplete="${config.autocomplete}"
              aria-describedby="${config.describedBy.join(" ")}"
              aria-errormessage="${config.errorId}"
            />
            ${helpMarkup}
            <p id="${config.errorId}" class="field-error" hidden></p>
          </div>
        `;
      }

      function SupportForm() {
        return `
          <section class="support-panel" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p class="panel-copy">
              Share your details below and we will respond as soon as possible.
            </p>
            <p class="required-key">Required fields are marked with <span aria-hidden="true">*</span>.</p>
            <form id="support-form" novalidate>
              ${FormField({
                id: "full-name",
                name: "fullName",
                label: "Full name",
                type: "text",
                required: true,
                autocomplete: "name",
                describedBy: ["full-name-error"],
                errorId: "full-name-error"
              })}
              ${FormField({
                id: "email-address",
                name: "email",
                label: "Email address",
                type: "email",
                required: true,
                autocomplete: "email",
                describedBy: ["email-address-error"],
                errorId: "email-address-error"
              })}
              ${FormField({
                id: "phone-number",
                name: "phone",
                label: "Phone number",
                type: "tel",
                required: false,
                autocomplete: "tel",
                describedBy: ["phone-number-help", "phone-number-error"],
                helpId: "phone-number-help",
                helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
                errorId: "phone-number-error"
              })}
              <div class="submit-row">
                <button type="submit">Send request</button>
                <p id="form-status" class="form-status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const fieldConfig = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Error: Enter your full name.";
          }
        },
        email: {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          validate(value, input) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }

            return input.validity.typeMismatch ? "Error: Enter an email address like name@example.com." : "";
          }
        },
        phone: {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-number-error"),
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            const phonePattern = /^[+]?[\d\s().-]{7,}$/;
            return phonePattern.test(value.trim())
              ? ""
              : "Error: Enter a phone number in a format like (555) 123-4567.";
          }
        }
      };

      let hasSubmitted = false;

      function showError(input, errorNode, message) {
        if (message) {
          input.setAttribute("aria-invalid", "true");
          errorNode.textContent = message;
          errorNode.hidden = false;
          return;
        }

        input.removeAttribute("aria-invalid");
        errorNode.textContent = "";
        errorNode.hidden = true;
      }

      function validateField(name) {
        const { input, error, validate } = fieldConfig[name];
        const message = validate(input.value, input);
        showError(input, error, message);
        return message;
      }

      Object.keys(fieldConfig).forEach((name) => {
        const { input } = fieldConfig[name];

        input.addEventListener("blur", () => {
          input.dataset.touched = "true";
          validateField(name);
        });

        input.addEventListener("input", () => {
          if (hasSubmitted || input.dataset.touched === "true") {
            validateField(name);
          }

          status.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        hasSubmitted = true;
        status.textContent = "";

        const invalidFields = Object.keys(fieldConfig).filter((name) => {
          const message = validateField(name);
          return Boolean(message);
        });

        if (invalidFields.length > 0) {
          fieldConfig[invalidFields[0]].input.focus();
          status.textContent = "Please correct the highlighted fields and try again.";
          return;
        }

        form.reset();
        Object.values(fieldConfig).forEach(({ input, error }) => {
          delete input.dataset.touched;
          showError(input, error, "");
        });
        hasSubmitted = false;
        status.textContent = "Thanks. Your support request is ready to send.";
      });
    </script>
  </body>
</html>
