    <title>Support Contact - Product Support</title>
    <style>
      :root {
        --bg: #f4f7fb;
        --panel: rgba(255, 255, 255, 0.9);
        --panel-border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #475569;
        --accent: #4f46e5;
        --accent-dark: #3730a3;
        --danger: #b42318;
        --danger-soft: #fef3f2;
        --input-border: #cbd5e1;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(79, 70, 229, 0.18), transparent 30%),
          radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 28%),
          var(--bg);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: #ffffff;
        color: var(--text);
        box-shadow: var(--shadow);
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4rem 0;
      }

      .support-layout {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(320px, 480px);
        gap: 2rem;
        align-items: center;
      }

      .support-copy,
      .support-panel {
        background: var(--panel);
        backdrop-filter: blur(18px);
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
      }

      .support-copy {
        padding: 2.5rem;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: rgba(79, 70, 229, 0.1);
        color: var(--accent-dark);
        font-size: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2.1rem, 4vw, 3.6rem);
        line-height: 1.05;
      }

      .lead {
        margin: 0;
        max-width: 38rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .feature-list {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 1rem;
        margin: 2rem 0 0;
        padding: 0;
        list-style: none;
      }

      .feature-list li {
        padding: 1rem 1.1rem;
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.72);
        border: 1px solid rgba(148, 163, 184, 0.18);
      }

      .feature-list strong {
        display: block;
        margin-bottom: 0.3rem;
        font-size: 0.95rem;
      }

      .support-panel {
        padding: 2rem;
      }

      .support-panel h2 {
        margin: 0 0 0.5rem;
        font-size: 1.4rem;
      }

      .panel-copy {
        margin: 0 0 1.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      .required-key {
        margin: 0 0 1.25rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      form {
        display: grid;
        gap: 1.1rem;
      }

      .form-field {
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
      }

      label {
        font-weight: 700;
      }

      .required-indicator {
        color: var(--accent-dark);
      }

      input {
        width: 100%;
        border: 1px solid var(--input-border);
        border-radius: 16px;
        padding: 0.95rem 1rem;
        font: inherit;
        color: var(--text);
        background: #ffffff;
        transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
      }

      input:hover {
        border-color: #94a3b8;
      }

      input:focus-visible,
      button:focus-visible {
        outline: 3px solid #312e81;
        outline-offset: 2px;
      }

      input:focus-visible {
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.12);
      }

      .field-help,
      .field-error,
      .form-status {
        margin: 0;
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .field-help {
        color: var(--muted);
      }

      .field-error {
        padding: 0.7rem 0.8rem;
        border-radius: 14px;
        background: var(--danger-soft);
        color: var(--danger);
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.1);
      }

      .submit-row {
        display: flex;
        flex-direction: column;
        gap: 0.85rem;
        margin-top: 0.4rem;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.3rem;
        font: inherit;
        font-weight: 700;
        color: #ffffff;
        background: linear-gradient(135deg, var(--accent), #0f9cf3);
        cursor: pointer;
        transition: transform 150ms ease, box-shadow 150ms ease;
        box-shadow: 0 16px 28px rgba(79, 70, 229, 0.28);
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 32px rgba(79, 70, 229, 0.34);
      }

      .form-status {
        min-height: 1.5rem;
        color: var(--accent-dark);
        font-weight: 600;
      }

      @media (max-width: 860px) {
        .page-shell {
          padding: 1.25rem 0 2rem;
        }

        .support-layout {
          grid-template-columns: 1fr;
        }

        .support-copy,
        .support-panel {
          padding: 1.5rem;
        }
      }

      @media (forced-colors: active) {
        .support-copy,
        .support-panel,
        .feature-list li,
        input,
        button,
        .field-error,
        .skip-link {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button {
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="root"></div>
    <script>
      function App() {
        return `
          <main id="maincontent" class="page-shell" tabindex="-1">
            <div class="support-layout">
              ${SupportCopy()}
              ${SupportForm()}
            </div>
          </main>
        `;
      }

      function SupportCopy() {
        return `
          <section class="support-copy" aria-labelledby="support-title">
            <span class="eyebrow">Support team</span>
            <h1 id="support-title">Get help from our product specialists.</h1>
            <p class="lead">
              Reach out with account questions, onboarding issues, or product feedback and our team
              will route your request to the right specialist.
            </p>
            <ul class="feature-list" aria-label="Support highlights">
              <li>
                <strong>Fast triage</strong>
                Requests land with the right team from the start.
              </li>
              <li>
                <strong>Clear follow-up</strong>
                Required contact details help us reply without delay.
              </li>
              <li>
                <strong>Flexible contact</strong>
                Add a phone number if a call is easier for you.
              </li>
            </ul>
          </section>
        `;
      }

      function FormField(config) {
        const helpMarkup = config.helpText
          ? `<p id="${config.helpId}" class="field-help">${config.helpText}</p>`
          : "";

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${config.id}"
              name="${config.name}"
              type="${config.type}"
              ${config.required ? "required" : ""}
              autocomplete="${config.autocomplete}"
              aria-describedby="${config.describedBy.join(" ")}"
              aria-errormessage="${config.errorId}"
            />
            ${helpMarkup}
            <p id="${config.errorId}" class="field-error" hidden></p>
          </div>
        `;
      }

      function SupportForm() {
        return `
          <section class="support-panel" aria-labelledby="contact-form-title">
            <h2 id="contact-form-title">Contact support</h2>
            <p class="panel-copy">
              Share your details below and we will respond as soon as possible.
            </p>
            <p class="required-key">Required fields are marked with <span aria-hidden="true">*</span>.</p>
            <form id="support-form" novalidate>
              ${FormField({
                id: "full-name",
                name: "fullName",
                label: "Full name",
                type: "text",
                required: true,
                autocomplete: "name",
                describedBy: ["full-name-error"],
                errorId: "full-name-error"
              })}
              ${FormField({
                id: "email-address",
                name: "email",
                label: "Email address",
                type: "email",
                required: true,
                autocomplete: "email",
                describedBy: ["email-address-error"],
                errorId: "email-address-error"
              })}
              ${FormField({
                id: "phone-number",
                name: "phone",
                label: "Phone number",
                type: "tel",
                required: false,
                autocomplete: "tel",
                describedBy: ["phone-number-help", "phone-number-error"],
                helpId: "phone-number-help",
                helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
                errorId: "phone-number-error"
              })}
              <div class="submit-row">
                <button type="submit">Send request</button>
                <p id="form-status" class="form-status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const fieldConfig = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Error: Enter your full name.";
          }
        },
        email: {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          validate(value, input) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }

            return input.validity.typeMismatch ? "Error: Enter an email address like name@example.com." : "";
          }
        },
        phone: {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-number-error"),
          validate(value) {
            if (!value.trim()) {
              return "";
            }

            const phonePattern = /^[+]?[\d\s().-]{7,}$/;
            return phonePattern.test(value.trim())
              ? ""
              : "Error: Enter a phone number in a format like (555) 123-4567.";
          }
        }
      };

      let hasSubmitted = false;

      function showError(input, errorNode, message) {
        if (message) {
          input.setAttribute("aria-invalid", "true");
          errorNode.textContent = message;
          errorNode.hidden = false;
          return;
        }

        input.removeAttribute("aria-invalid");
        errorNode.textContent = "";
        errorNode.hidden = true;
      }

      function validateField(name) {
        const { input, error, validate } = fieldConfig[name];
        const message = validate(input.value, input);
        showError(input, error, message);
        return message;
      }

      Object.keys(fieldConfig).forEach((name) => {
        const { input } = fieldConfig[name];

        input.addEventListener("blur", () => {
          input.dataset.touched = "true";
          validateField(name);
        });

        input.addEventListener("input", () => {
          if (hasSubmitted || input.dataset.touched === "true") {
            validateField(name);
          }

          status.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        hasSubmitted = true;
        status.textContent = "";

        const invalidFields = Object.keys(fieldConfig).filter((name) => {
          const message = validateField(name);
          return Boolean(message);
        });

        if (invalidFields.length > 0) {
          fieldConfig[invalidFields[0]].input.focus();
          status.textContent = "Please correct the highlighted fields and try again.";
          return;
        }

        form.reset();
        Object.values(fieldConfig).forEach(({ input, error }) => {
          delete input.dataset.touched;
          showError(input, error, "");
        });
        hasSubmitted = false;
        status.textContent = "Thanks. Your support request is ready to send.";
      });
    </script>
  </body>
</html>
